133	        {/* ── Google Analytics (gtag.js) — G-VSPBSV4406 ──────── */}
134	        <Script
135	          src="https://www.googletagmanager.com/gtag/js?id=G-VSPBSV4406"
136	          strategy="afterInteractive"
137	        />
138	        <Script
139	          id="gtag-init"
140	          strategy="afterInteractive"
141	          dangerouslySetInnerHTML={{
142	            __html: `
143	              window.dataLayer = window.dataLayer || [];
144	              function gtag(){dataLayer.push(arguments);}
145	              gtag('js', new Date());
146	              gtag('config', 'G-VSPBSV4406');
147	            `,
148	          }}
149	        />
150	
151	        {/* ── Microsoft Clarity — v2sdjrzf16 ─────────────────── */}
152	        <Script
153	          id="clarity-init"
154	          strategy="afterInteractive"
155	          dangerouslySetInnerHTML={{
156	            __html: `
157	              (function(c,l,a,r,i,t,y){
158	                c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};
159	                t=l.createElement(r);t.async=1;t.src="https://www.clarity.ms/tag/"+i;
160	                y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);
161	              })(window, document, "clarity", "script", "v2sdjrzf16");
162	            `,
163	          }}
164	        />
165	
166	        {/* ── Contentsquare ──────────────────────────────────── */}
167	        <Script
168	          src="https://t.contentsquare.net/uxa/82f0998b73803.js"
169	          strategy="afterInteractive"
170	        />
171	
172	        {/* ── Chatwoot (hardcoded token from Webflow) ─────────── */}
173	        <Script
174	          id="chatwoot-sdk"
175	          strategy="afterInteractive"
176	          dangerouslySetInnerHTML={{
177	            __html: `
178	              if (window.self === window.top) {
179	                (function(d,t) {
180	                  var BASE_URL="https://app.chatwoot.com";
181	                  var g=d.createElement(t),s=d.getElementsByTagName(t)[0];
182	                  g.src=BASE_URL+"/packs/js/sdk.js";
183	                  g.async=true;
184	                  s.parentNode.insertBefore(g,s);
185	                  g.onload=function(){
186	                    window.chatwootSDK.run({
187	                      websiteToken: 'i6RsELa1Smu1Gp6ayBrvTiQj',
188	                      baseUrl: BASE_URL
189	                    })
190	                  }
191	                })(document,"script");
192	              }
193	            `,
194	          }}
195	        />
196	
197	        {/* ── Chatwoot aria-label fix ─────────────────────────── */}
198	        <Script
199	          id="chatwoot-aria"
200	          strategy="afterInteractive"
201	          dangerouslySetInnerHTML={{
202	            __html: `
203	              function fixChatwootAria() {
204	                var openBtn = document.querySelector('.woot-widget-bubble:not(.woot--close)');
205	                var closeBtn = document.querySelector('.woot-widget-bubble.woot--close');
206	                if (openBtn && !openBtn.getAttribute('aria-label')) openBtn.setAttribute('aria-label', 'Open chat window');
207	                if (closeBtn && !closeBtn.getAttribute('aria-label')) closeBtn.setAttribute('aria-label', 'Close chat window');
208	              }
209	              fixChatwootAria();
210	              new MutationObserver(fixChatwootAria).observe(document.body, { childList: true, subtree: true });
211	            `,
212	          }}
213	        />
214	      </body>
215	    </html>
216	  );
217	}
