39	export function ContactFormSection() {
40	  const [fields, setFields] = useState<ContactFields>(INITIAL);
41	  const [errors, setErrors] = useState<FieldErrors>({});
42	  const [status, setStatus] = useState<FormStatus>("idle");
43	
44	  function validateField(name: keyof ContactFields, value: string) {
45	    const result = ContactSchema.safeParse({ ...fields, [name]: value });
46	    if (!result.success) {
47	      const fieldError = result.error.flatten().fieldErrors[name];
48	      setErrors((prev) => ({
49	        ...prev,
50	        [name]: fieldError?.[0] ?? undefined,
51	      }));
52	    } else {
53	      setErrors((prev) => ({ ...prev, [name]: undefined }));
54	    }
55	  }
56	
57	  function handleChange(
58	    e: React.ChangeEvent<
59	      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
60	    >
61	  ) {
62	    const { name, value } = e.target;
63	    setFields((prev) => ({ ...prev, [name]: value }));
64	  }
65	
66	  function handleBlur(
67	    e: React.FocusEvent<
68	      HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement
69	    >
70	  ) {
71	    const { name, value } = e.target;
72	    validateField(name as keyof ContactFields, value);
73	  }
